/*
-- Query: SELECT * FROM kkpl.quotations
LIMIT 0, 1000

-- Date: 2025-06-17 18:09
*/
CREATE TABLE `quotations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `quotationId` varchar(20) NOT NULL,
  `customerName` varchar(100) NOT NULL,
  `customerEmail` varchar(100) DEFAULT NULL,
  `customerPhone` varchar(20) DEFAULT NULL,
  `productName` varchar(100) NOT NULL,
  `quantity` int NOT NULL,
  `unitPrice` decimal(10,2) NOT NULL,
  `quotationDate` datetime DEFAULT CURRENT_TIMESTAMP,
  `validTill` date DEFAULT NULL,
  `quotStatus` varchar(20) DEFAULT 'Pending',
  `remarks` text,
  `createdAt` datetime DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updatedBy` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `quotationId` (`quotationId`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


